     1→//! HID Device Management
     2→//!
     3→//! Handles detection and management of USB HID devices.
     4→
     5→use super::{HidConfig, HidDeviceEvent, HidError, KNOWN_DEVICES};
     6→use std::sync::Arc;
     7→use tokio::sync::{broadcast, RwLock};
     8→use uuid::Uuid;
     9→
    10→/// Represents a USB HID device
    11→#[derive(Debug, Clone)]
    12→pub struct HidDevice {
    13→    /// Unique identifier
    14→    pub id: Uuid,
    15→    /// USB vendor ID
    16→    pub vendor_id: u16,
    17→    /// USB product ID
    18→    pub product_id: u16,
    19→    /// Device name
    20→    pub name: String,
    21→    /// Serial number if available
    22→    pub serial_number: Option<String>,
    23→    /// Number of buttons (if known)
    24→    pub button_count: Option<u8>,
    25→    /// Current status
    26→    pub status: HidDeviceStatus,
    27→    /// Whether this is a known/supported device
    28→    pub is_known: bool,
    29→}
    30→
    31→/// Device status
    32→#[derive(Debug, Clone, PartialEq, Eq)]
    33→pub enum HidDeviceStatus {
    34→    /// Device detected but not opened
    35→    Detected,
    36→    /// Device is opening
    37→    Opening,
    38→    /// Device is open and ready
    39→    Open,
    40→    /// Device has an error
    41→    Error(String),
    42→    /// Device was disconnected
    43→    Disconnected,
    44→}
    45→
    46→impl HidDevice {
    47→    /// Create a new HID device
    48→    pub fn new(vendor_id: u16, product_id: u16, name: String) -> Self {
    49→        let known = KNOWN_DEVICES
    50→            .iter()
    51→            .find(|d| d.vendor_id == vendor_id && d.product_id == product_id);
    52→
    53→        Self {
    54→            id: Uuid::new_v4(),
    55→            vendor_id,
    56→            product_id,
    57→            name,
    58→            serial_number: None,
    59→            button_count: known.map(|d| d.button_count),
    60→            status: HidDeviceStatus::Detected,
    61→            is_known: known.is_some(),
    62→        }
    63→    }
    64→
    65→    /// Check if device is open
    66→    pub fn is_open(&self) -> bool {
    67→        matches!(self.status, HidDeviceStatus::Open)
    68→    }
    69→
    70→    /// Get device path for display
    71→    pub fn display_path(&self) -> String {
    72→        format!("{:04X}:{:04X}", self.vendor_id, self.product_id)
    73→    }
    74→}
    75→
    76→/// Trait for HID device management
    77→pub trait HidDeviceManager: Send + Sync {
    78→    /// Scan for connected HID devices
    79→    fn scan_devices(&self) -> Vec<HidDevice>;
    80→
    81→    /// Start monitoring for device connect/disconnect
    82→    fn start_monitoring(&self) -> impl std::future::Future<Output = Result<(), HidError>> + Send;
    83→
    84→    /// Stop monitoring
    85→    fn stop_monitoring(&self);
    86→
    87→    /// Get device by ID
    88→    fn get_device(&self, device_id: &Uuid) -> Option<HidDevice>;
    89→
    90→    /// Open device for input
    91→    fn open_device(
    92→        &self,
    93→        device_id: &Uuid,
    94→    ) -> impl std::future::Future<Output = Result<(), HidError>> + Send;
    95→
    96→    /// Close device
    97→    fn close_device(
    98→        &self,
    99→        device_id: &Uuid,
   100→    ) -> impl std::future::Future<Output = Result<(), HidError>> + Send;
   101→
   102→    /// Check if device is open
   103→    fn is_open(&self, device_id: &Uuid) -> bool;
   104→
   105→    /// Enable/disable device
   106→    fn set_enabled(&self, device_id: &Uuid, enabled: bool);
   107→
   108→    /// Subscribe to device events
   109→    fn subscribe_events(&self) -> broadcast::Receiver<HidDeviceEvent>;
   110→}
   111→
   112→/// Default HID device manager implementation
   113→pub struct DefaultHidDeviceManager {
   114→    devices: Arc<RwLock<Vec<HidDevice>>>,
   115→    event_tx: broadcast::Sender<HidDeviceEvent>,
   116→    is_monitoring: Arc<RwLock<bool>>,
   117→    _config: HidConfig,
   118→}
   119→
   120→impl DefaultHidDeviceManager {
   121→    /// Create a new device manager
   122→    pub fn new(config: HidConfig) -> Self {
   123→        let (event_tx, _) = broadcast::channel(100);
   124→
   125→        Self {
   126→            devices: Arc::new(RwLock::new(Vec::new())),
   127→            event_tx,
   128→            is_monitoring: Arc::new(RwLock::new(false)),
   129→            _config: config,
   130→        }
   131→    }
   132→}
   133→
   134→impl HidDeviceManager for DefaultHidDeviceManager {
   135→    fn scan_devices(&self) -> Vec<HidDevice> {
   136→        tracing::info!("Scanning for HID devices...");
   137→
   138→        let found = Vec::new();
   139→
   140→        // TODO: Use hidapi to enumerate devices
   141→        // let api = HidApi::new().unwrap();
   142→        // for device in api.device_list() {
   143→        //     if let Some(known) = find_known_device(device.vendor_id(), device.product_id()) {
   144→        //         found.push(HidDevice::new(
   145→        //             device.vendor_id(),
   146→        //             device.product_id(),
   147→        //             known.name.to_string(),
   148→        //         ));
   149→        //     }
   150→        // }
   151→
   152→        tracing::debug!("Found {} HID devices", found.len());
   153→
   154→        found
   155→    }
   156→
   157→    async fn start_monitoring(&self) -> Result<(), HidError> {
   158→        *self.is_monitoring.write().await = true;
   159→
   160→        tracing::info!("Started HID device monitoring");
   161→
   162→        // TODO: Start background task to monitor for device changes
   163→        // This would use platform-specific APIs or polling
   164→
   165→        Ok(())
   166→    }
   167→
   168→    fn stop_monitoring(&self) {
   169→        if let Ok(mut monitoring) = self.is_monitoring.try_write() {
   170→            *monitoring = false;
   171→        }
   172→
   173→        tracing::info!("Stopped HID device monitoring");
   174→    }
   175→
   176→    fn get_device(&self, device_id: &Uuid) -> Option<HidDevice> {
   177→        self.devices
   178→            .try_read()
   179→            .ok()?
   180→            .iter()
   181→            .find(|d| &d.id == device_id)
   182→            .cloned()
   183→    }
   184→
   185→    async fn open_device(&self, device_id: &Uuid) -> Result<(), HidError> {
   186→        let mut devices = self.devices.write().await;
   187→
   188→        let device = devices
   189→            .iter_mut()
   190→            .find(|d| &d.id == device_id)
   191→            .ok_or(HidError::DeviceNotFound(*device_id))?;
   192→
   193→        device.status = HidDeviceStatus::Opening;
   194→
   195→        tracing::info!("Opening HID device: {}", device.name);
   196→
   197→        // TODO: Actually open the device using hidapi
   198→        // let api = HidApi::new()?;
   199→        // let handle = api.open(device.vendor_id, device.product_id)?;
   200→
   201→        device.status = HidDeviceStatus::Open;
   202→
   203→        let _ = self.event_tx.send(HidDeviceEvent::DeviceOpened(*device_id));
   204→
   205→        Ok(())
   206→    }
   207→
   208→    async fn close_device(&self, device_id: &Uuid) -> Result<(), HidError> {
   209→        let mut devices = self.devices.write().await;
   210→
   211→        let device = devices
   212→            .iter_mut()
   213→            .find(|d| &d.id == device_id)
   214→            .ok_or(HidError::DeviceNotFound(*device_id))?;
   215→
   216→        tracing::info!("Closing HID device: {}", device.name);
   217→
   218→        // TODO: Close the device handle
   219→
   220→        device.status = HidDeviceStatus::Detected;
   221→
   222→        let _ = self.event_tx.send(HidDeviceEvent::DeviceClosed(*device_id));
   223→
   224→        Ok(())
   225→    }
   226→
   227→    fn is_open(&self, device_id: &Uuid) -> bool {
   228→        self.devices
   229→            .try_read()
   230→            .ok()
   231→            .and_then(|d| {
   232→                d.iter()
   233→                    .find(|dev| &dev.id == device_id)
   234→                    .map(|dev| dev.is_open())
   235→            })
   236→            .unwrap_or(false)
   237→    }
   238→
   239→    fn set_enabled(&self, _device_id: &Uuid, _enabled: bool) {
   240→        // TODO: Update device enabled state in config
   241→    }
   242→
   243→    fn subscribe_events(&self) -> broadcast::Receiver<HidDeviceEvent> {
   244→        self.event_tx.subscribe()
   245→    }
   246→}
