   252→    #[test]
   253→    fn test_device_creation() {
   254→        let device = HidDevice::new(0x0FD9, 0x0060, "Stream Deck".to_string());
   255→
   256→        assert!(device.is_known);
   257→        assert_eq!(device.button_count, Some(15));
   258→        assert!(!device.is_open());
   259→    }
   260→
   261→    #[test]
   262→    fn test_unknown_device() {
   263→        let device = HidDevice::new(0x1234, 0x5678, "Unknown Device".to_string());
   264→
   265→        assert!(!device.is_known);
   266→        assert!(device.button_count.is_none());
   267→    }
   268→
   269→    #[test]
   270→    fn test_display_path() {
   271→        let device = HidDevice::new(0x0FD9, 0x0060, "Stream Deck".to_string());
