    11→/// Represents a USB HID device
    12→#[derive(Debug, Clone)]
    13→pub struct HidDevice {
    14→    /// Unique identifier
    15→    pub id: Uuid,
    16→    /// USB vendor ID
    17→    pub vendor_id: u16,
    18→    /// USB product ID
    19→    pub product_id: u16,
    20→    /// Device name
    21→    pub name: String,
    22→    /// Serial number if available
    23→    pub serial_number: Option<String>,
    24→    /// Number of buttons (if known)
    25→    pub button_count: Option<u8>,
    26→    /// Current status
    27→    pub status: HidDeviceStatus,
    28→    /// Whether this is a known/supported device
    29→    pub is_known: bool,
    30→}
    31→
    32→/// Device status
    33→#[derive(Debug, Clone, PartialEq, Eq)]
    34→pub enum HidDeviceStatus {
    35→    /// Device detected but not opened
    36→    Detected,
    37→    /// Device is opening
    38→    Opening,
    39→    /// Device is open and ready
    40→    Open,
    41→    /// Device has an error
    42→    Error(String),
    43→    /// Device was disconnected
    44→    Disconnected,
    45→}
    46→
    47→impl HidDevice {
    48→    /// Create a new HID device
    49→    pub fn new(vendor_id: u16, product_id: u16, name: String) -> Self {
    50→        let known = KNOWN_DEVICES
    51→            .iter()
    52→            .find(|d| d.vendor_id == vendor_id && d.product_id == product_id);
    53→
    54→        Self {
    55→            id: Uuid::new_v4(),
    56→            vendor_id,
    57→            product_id,
    58→            name,
    59→            serial_number: None,
    60→            button_count: known.map(|d| d.button_count),
    61→            status: HidDeviceStatus::Detected,
    62→            is_known: known.is_some(),
    63→        }
    64→    }
    65→
    66→    /// Check if device is open
    67→    pub fn is_open(&self) -> bool {
    68→        matches!(self.status, HidDeviceStatus::Open)
    69→    }
    70→
    71→    /// Get device path for display
    72→    pub fn display_path(&self) -> String {
    73→        format!("{:04X}:{:04X}", self.vendor_id, self.product_id)
    74→    }
    75→}
