     1→//! HID Device Management
     2→//!
     3→//! Handles detection and management of USB HID devices.
     4→
     5→use super::{find_known_device, HidConfig, HidDeviceEvent, HidError, KNOWN_DEVICES};
     6→use hidapi::HidApi;
     7→use std::collections::{HashMap, HashSet};
     8→use std::ffi::CString;
     9→use std::sync::{Arc, Mutex};
    10→use std::time::Duration;
    11→use tokio::sync::{broadcast, RwLock};
    12→use uuid::Uuid;
    13→
    14→/// Represents a USB HID device
    15→#[derive(Debug, Clone)]
    16→pub struct HidDevice {
    17→    /// Unique identifier
    18→    pub id: Uuid,
    19→    /// USB vendor ID
    20→    pub vendor_id: u16,
    21→    /// USB product ID
    22→    pub product_id: u16,
    23→    /// Device name
    24→    pub name: String,
    25→    /// Serial number if available
    26→    pub serial_number: Option<String>,
    27→    /// Device path for opening (platform-specific)
    28→    pub device_path: Option<String>,
    29→    /// Number of buttons (if known)
    30→    pub button_count: Option<u8>,
    31→    /// Current status
    32→    pub status: HidDeviceStatus,
    33→    /// Whether this is a known/supported device
    34→    pub is_known: bool,
    35→}
    36→
    37→/// Device status
    38→#[derive(Debug, Clone, PartialEq, Eq)]
    39→pub enum HidDeviceStatus {
    40→    /// Device detected but not opened
    41→    Detected,
    42→    /// Device is opening
    43→    Opening,
    44→    /// Device is open and ready
    45→    Open,
    46→    /// Device has an error
    47→    Error(String),
    48→    /// Device was disconnected
    49→    Disconnected,
    50→}
    51→
    52→impl HidDevice {
    53→    /// Create a new HID device
    54→    pub fn new(vendor_id: u16, product_id: u16, name: String) -> Self {
    55→        let known = KNOWN_DEVICES
    56→            .iter()
    57→            .find(|d| d.vendor_id == vendor_id && d.product_id == product_id);
    58→
    59→        Self {
    60→            id: Uuid::new_v4(),
    61→            vendor_id,
    62→            product_id,
    63→            name,
    64→            serial_number: None,
    65→            device_path: None,
    66→            button_count: known.map(|d| d.button_count),
    67→            status: HidDeviceStatus::Detected,
    68→            is_known: known.is_some(),
    69→        }
    70→    }
    71→
    72→    /// Check if device is open
    73→    pub fn is_open(&self) -> bool {
    74→        matches!(self.status, HidDeviceStatus::Open)
    75→    }
    76→
    77→    /// Get device path for display
    78→    pub fn display_path(&self) -> String {
    79→        format!("{:04X}:{:04X}", self.vendor_id, self.product_id)
    80→    }
    81→
    82→    /// Get a unique identity key for tracking devices across scans
    83→    /// Uses VID:PID:Serial (or VID:PID:Path if no serial)
    84→    fn identity_key(&self) -> String {
    85→        if let Some(ref serial) = self.serial_number {
    86→            format!("{:04X}:{:04X}:{}", self.vendor_id, self.product_id, serial)
    87→        } else if let Some(ref path) = self.device_path {
    88→            format!("{:04X}:{:04X}:{}", self.vendor_id, self.product_id, path)
    89→        } else {
    90→            format!("{:04X}:{:04X}", self.vendor_id, self.product_id)
    91→        }
    92→    }
    93→}
    94→
    95→/// Trait for HID device management
    96→pub trait HidDeviceManager: Send + Sync {
    97→    /// Scan for connected HID devices
    98→    fn scan_devices(&self) -> Vec<HidDevice>;
    99→
   100→    /// Start monitoring for device connect/disconnect
   101→    fn start_monitoring(&self) -> impl std::future::Future<Output = Result<(), HidError>> + Send;
   102→
   103→    /// Stop monitoring
   104→    fn stop_monitoring(&self);
   105→
   106→    /// Get device by ID
   107→    fn get_device(&self, device_id: &Uuid) -> Option<HidDevice>;
   108→
   109→    /// Open device for input
   110→    fn open_device(
   111→        &self,
   112→        device_id: &Uuid,
   113→    ) -> impl std::future::Future<Output = Result<(), HidError>> + Send;
   114→
   115→    /// Close device
   116→    fn close_device(
   117→        &self,
   118→        device_id: &Uuid,
   119→    ) -> impl std::future::Future<Output = Result<(), HidError>> + Send;
   120→
   121→    /// Check if device is open
   122→    fn is_open(&self, device_id: &Uuid) -> bool;
   123→
   124→    /// Enable/disable device
   125→    fn set_enabled(&self, device_id: &Uuid, enabled: bool);
   126→
   127→    /// Subscribe to device events
   128→    fn subscribe_events(&self) -> broadcast::Receiver<HidDeviceEvent>;
   129→}
