   700→    async fn close_device(&self, device_id: &Uuid) -> Result<(), HidError> {
   701→        // Get device name for logging
   702→        let device_name = {
   703→            let devices = self.devices.read().await;
   704→            devices
   705→                .iter()
   706→                .find(|d| &d.id == device_id)
   707→                .map(|d| d.name.clone())
   708→                .ok_or(HidError::DeviceNotFound(*device_id))?
   709→        };
   710→
   711→        tracing::info!("Closing HID device: {}", device_name);
   712→
   713→        // Remove the handle from storage (dropping it closes the device)
   714→        let was_open = {
   715→            let mut handles = self.device_handles.lock().map_err(|e| {
   716→                HidError::OpenFailed(format!("Failed to lock device handles: {}", e))
   717→            })?;
   718→            handles.remove(device_id).is_some()
   719→        };
   720→
   721→        if !was_open {
   722→            tracing::warn!("Device {} was not open", device_name);
   723→            return Err(HidError::DeviceNotOpen);
   724→        }
   725→
   726→        // Update device status
